package com.example.helpdesk.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String username; @Column(nullable=false) private String password; @Column(name="full_name",nullable=false) private String fullName; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role; @Column(name="created_at",nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); public User(){} public User(String u,String p,String n,Role r){username=u;password=p;fullName=n;role=r;} public Long getId(){return id;} public String getUsername(){return username;} public String getPassword(){return password;} public String getFullName(){return fullName;} public Role getRole(){return role;} }
